  ["e00046ff35ac6b95"] = { "そなたたちのことは聞いている。Windshaper。古のEldre'Thalasの道を外れた子らよ。\n\nかつての我なら、そなたたちを同族と呼んだであろう。遠い同族ではあるがな。だが今の我には、エルフ族との共通点など、ほかのどの生ある種族との共通点と同じほどしかない。息をするあらゆる生き物について我が重んじるのは、それがどれほどForsakenの目的を進められるか、ただそれだけだ。我が民の役に立て。そうすれば、我らの地で歓迎されよう。\n\n行け。好きなようにUndercityを見て回り、その安らぎを楽しむがよい、ささやかなものではあるがな。ただ覚えておけ、我が領域の内で、我の目を逃れるものは何ひとつない。", "." },
  ["e005183a03a3afee"] = { "教えられることはお教えします。一つ一つの教えは、女神ご自身からの贈り物です。その贈り物を賢く用いれば、あなたが挫けることはないでしょう。", "." },
  ["e0054f92fb2a5a31"] = { "もちろんです、{name}。\n\nDawnからReveredと見なされている冒険者は、優れた品を手に入れるために合計14個の記章を納めなければなりません。さらに強力な品を手に入れるには、合計90個の記章を納める必要があります。\n\nDawnからReveredと見なされている者にとって、優れた品の代価はかなり手頃に感じられるでしょう！より強力な品の代価は、それでもなお高いままですが。", "." },
  ["e00697f8b57d4f64"] = { "もう見つけたか、{name}? Searing Bladeの指導者どもを。\n\nShadow CouncilがOrgrimmarとHordeのすべてを私から奪おうとしていることは分かっていた。だが、奴らがこれほど早く街に潜り込めるとは思っていなかった。この獣には腕がいくつもある……疲れ果てるまで切り落とし続けても、始めた時から一歩も進んではいないだろう。密偵たちには倍の働きをさせねばなるまい。", "." },
  ["e00dfbafbe8916ea"] = { "Gimlok、服を汚すんじゃないよ。", "." },
  ["e0152b4a996cdf1c"] = { "ハンターの道を教えてやろう。", "." },
  ["e0238426ebf72fdb"] = { "この仕事のこういうところが嫌いなんだ。ああ、Duskwoodよ、哀れなAntonioにお手柔らかに。", "." },
  ["e02b2167bffbd654"] = { "Sulの双剣は決して見つけられぬぞ。", "." },
  ["e02e6f6131d0aaad"] = { "Kel'Thuzadは杖を復元しようと相当な労力を注いできた。その破片はかつて、KalimdorからSouth Seasまで、この世界中に散らばっていた。私自身、一時は20個の破片を所持していた——Kel'Thuzadの手下どもに奪われるまではな。それが、私がここにいる理由だ。", "." },
  ["e03239dab4a2c997"] = { "やっと誰か来やがったか。何をぐずぐずしていた？ああ、いい、気にするな。援護しろ、兵士。俺は基地まで戻らねばならん！", "." },
  ["e0478c84606ee4b3"] = { "Zephrasは大きな危機にある。何千年も前に我々をこのSkywallへと連れてきた風の元素の精霊たちは我々を見捨て、この不安定な領域で我々を無防備なままにした。かつて栄えた我々の社会は、Skywallの我々の片隅にある複数の島の聖域にまたがっていたが、今では、この小さな島の外にほかのshen'doreiが残っているのかどうかさえ分からない。\n\n事態は深刻だが、High Orderはこの困難に立ち向かう決意だ。", "." },
  ["e04a327e9c9ac95e"] = { "%sは自分の喉を掻きむしった。", "." },
