  ["e070ed89e92a320c"] = { "Lok'tar、{class}、重要な知らせがある！Ahn'Qirajで戦が始まろうとしている。我々はそれに備えねばならん。俺はここで、手に入る限りのthick leatherを集めているんだ。今のところ$2070wある。だが大族長からは$2071wを集めるよう命じられていてな。見ての通り、少し足りん。", "." },
  ["e07144641c1285e3"] = { "ほう、ある程度その力量を示した同胞のウォーロックか。\n\nお会いできて嬉しいわ。私の名はMenara Voidrender……そう名乗るだけの理由もあってのことよ。\n\nあなたは、他の道具……もっと強力な道具……を渡しても歓迎されこそすれ、愚かに手渡したことにはならぬほどに、強く、十分な学識を備えているようね。それが本当なら、さらに私と話しなさい。そうでないなら、そうね、波止場へ戻って海へ出ていく道は分かっているでしょう。", "." },
  ["e072387cbbef9e7b"] = { "Defilerの高台を訪れたいと望むのなら、頼むだけでよい。私はあなたと仲間たちを転送することができる。", "." },
  ["e077635091b54305"] = { "{name}――Hordeの{class}――が大族長の不滅の敬意を勝ち取ったことをここに告げる。その者はTimbermaw Holdと大いなる外交を結び、我らに代わって勇敢な働きを示した。その者は義務の域をはるかに超える働きをしたのだ。{name}――真のHordeの英雄――に万歳を3回！", "." },
  ["e07dc839a73424e3"] = { "Shady Rest Innへ行って、足跡を追え。どこへ続いているか確かめて、私に報告してくれ。", "." },
