  ["e08b0bde265c1dec"] = { "本棚はこんなにあるのに、時間はこんなに少ない……", "." },
  ["e08cd4a7b5b7f443"] = { "助けてくれてありがとう！", "." },
  ["e08fa9da416384d7"] = { "十分な強さはないと思う。", "." },
  ["e08fd1f1b38c5a29"] = { "ああ、それに会いたいのなら、Thunder Bluffの高みまで行かねばなりません。Bloodhoof Villageから北へ伸びる道をたどってください。崖の麓には、頂上まで運んでくれる昇降機があります。着いたら、Bluffwatcherの誰かにさらに道を尋ねるとよいでしょう。", "." },
  ["e0969b6edf3f5d9e"] = { "降伏すりゃ命は助けてやるぞ、異教徒ども！武器を捨てて歩け！", "." },
  ["e09f39de91aa7bb1"] = { "見てもらいたい素晴らしいレシピがたくさんあるよ。しかも割引価格でね！", "." },
  ["e0a141a60a08d799"] = { "つまりお前は、Netherからinfernalの下僕を呼び降ろす秘密を学びにNibyのもとへ来たのだな。\n\n黙れ！Nibyはすべてを知っている！\n\nNibyはそう易々とその知識を手放しはせん。まずは、非常に重要な仕事でNibyを手伝うのだ。", "." },
